-- ============================================================
-- STEP 7: Admin Setup read-side stored procedures
-- ============================================================
-- ITOperationMaturity V2_13 - Read-side stored procedures for Admin Setup.
--
-- Scope: ONLY the multi-join/aggregating READ endpoints that are entirely
-- self-contained within this database (CSPdb / BAS_UAT). Endpoints that also
-- need PROJECT/CUSTOMER/EMP_INFO (Cldb) are NOT fully convertible - Cldb
-- lives on a different physical SQL Server (see RasEntities connection
-- string vs. "Conn" in Web.config), so there is no single-query JOIN across
-- them without a linked server. For those, this script covers the CSPdb-side
-- join/aggregation only; the Cldb-side name/project lookup stays in C#
-- exactly as it already does elsewhere in this controller.
--
-- Covers:
--   1. usp_ITOpsGetAssessmentCycles          (Step 2 list, GetITOpsAssessmentCycles)
--   2. usp_ITOpsGetAssessmentTeam             (Step 5, GetITOpsAssessmentTeam)
--   3. usp_ITOpsGetDomainProjectMapDomains    (Step 3b, GetITOpsDomainProjectMappings - domain side)
--   4. usp_ITOpsGetDomainProjectMapAssessees  (Step 3b, GetITOpsDomainProjectMappings - assessee side)
--   5. usp_ITOpsGetCategoriesForDomain        (Step 3c, GetITOpsCategoriesForDomain + GetITOpsCategoryVersions)

IF OBJECT_ID('dbo.usp_ITOpsGetAssessmentCycles', 'P') IS NOT NULL
    DROP PROCEDURE dbo.usp_ITOpsGetAssessmentCycles;
GO

-- One row per (cycle, status actually present in that cycle). A cycle with
-- zero assessments still comes back as one row with STATUS/CNT = NULL, so
-- the caller can tell "cycle exists, nothing created yet" apart from
-- "cycle doesn't exist". Replaces: cycles pulled whole + a second full
-- ITOPS_ASSESSMENT pull + two in-memory GroupBys per cycle.
CREATE PROCEDURE dbo.usp_ITOpsGetAssessmentCycles
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        m.ID              AS CycleId,
        m.CYCLE_LABEL     AS CycleLabel,
        m.START_DATE      AS StartDate,
        m.END_DATE        AS EndDate,
        m.STATUS          AS CycleStatus,
        m.DESCRIPTION     AS Description,
        s.STATUS          AS AssessmentStatus,
        s.Cnt             AS StatusCount
    FROM dbo.ITOPS_ASSESSMENT_MASTER m
    OUTER APPLY (
        SELECT
            CASE WHEN a.STATUS IS NULL OR LTRIM(RTRIM(a.STATUS)) = '' THEN 'NotStarted' ELSE a.STATUS END AS STATUS,
            COUNT(*) AS Cnt
        FROM dbo.ITOPS_ASSESSMENT a
        WHERE a.ISACTIVE = 1
          AND a.ASSESSMENT_MASTER_ID = m.ID
        GROUP BY CASE WHEN a.STATUS IS NULL OR LTRIM(RTRIM(a.STATUS)) = '' THEN 'NotStarted' ELSE a.STATUS END
    ) s
    WHERE m.ISACTIVE = 1
    ORDER BY m.START_DATE DESC, m.ID DESC, s.Cnt DESC, s.STATUS ASC;
END
GO

IF OBJECT_ID('dbo.usp_ITOpsGetAssessmentTeam', 'P') IS NOT NULL
    DROP PROCEDURE dbo.usp_ITOpsGetAssessmentTeam;
GO

-- One row per assessor/reviewer/assessee on the assessment, tagged by
-- RoleType. EmpName is resolved back in C# (GetITOpsEmpNameMap) since
-- EMP_INFO lives in Cldb, on a different server - see header note.
-- No primary/backup distinction - every assessor/reviewer on a domain is an
-- equal owner, ordered by insertion (ID) only.
CREATE PROCEDURE dbo.usp_ITOpsGetAssessmentTeam
    @AssessmentId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 'Assessor' AS RoleType, a.ID, a.ASSESSMENT_ID AS AssessmentId, a.ASSESSOR_EMP_ID AS EmpId
    FROM dbo.ITOPS_ASSESSMENT_ASSESSOR a
    WHERE a.ISACTIVE = 1 AND a.ASSESSMENT_ID = @AssessmentId

    UNION ALL

    SELECT 'Reviewer' AS RoleType, r.ID, r.ASSESSMENT_ID AS AssessmentId, r.REVIEWER_EMP_ID AS EmpId
    FROM dbo.ITOPS_ASSESSMENT_REVIEWER r
    WHERE r.ISACTIVE = 1 AND r.ASSESSMENT_ID = @AssessmentId

    UNION ALL

    SELECT 'Assessee' AS RoleType, e.ID, e.ASSESSMENT_ID AS AssessmentId, e.ASSESSEE_EMP_ID AS EmpId
    FROM dbo.ITOPS_ASSESSMENT_ASSESSEE e
    WHERE e.ISACTIVE = 1 AND e.ASSESSMENT_ID = @AssessmentId

    ORDER BY RoleType, ID;
END
GO

IF OBJECT_ID('dbo.usp_ITOpsGetDomainProjectMapDomains', 'P') IS NOT NULL
    DROP PROCEDURE dbo.usp_ITOpsGetDomainProjectMapDomains;
GO

-- One row per active (project, domain) mapping, domain fields already
-- joined in. @ProjectId NULL = every project (the grid's default load).
CREATE PROCEDURE dbo.usp_ITOpsGetDomainProjectMapDomains
    @ProjectId VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        map.ID          AS MappingId,
        map.PROJECT_ID  AS ProjectId,
        map.DOMAIN_ID   AS DomainId,
        d.CODE          AS DomainCode,
        d.NAME          AS DomainName
    FROM dbo.ITOPS_DOMAIN_PROJECT_MAP map
    INNER JOIN dbo.ITOPS_DOMAIN d ON d.ID = map.DOMAIN_ID
    WHERE map.ISACTIVE = 1
      AND (@ProjectId IS NULL OR map.PROJECT_ID = @ProjectId)
    ORDER BY map.PROJECT_ID, d.NAME;
END
GO

IF OBJECT_ID('dbo.usp_ITOpsGetDomainProjectMapAssessees', 'P') IS NOT NULL
    DROP PROCEDURE dbo.usp_ITOpsGetDomainProjectMapAssessees;
GO

-- One row per active project assessee. Name is resolved in C# against
-- Cldb.EMP_INFO (different server - see header note).
CREATE PROCEDURE dbo.usp_ITOpsGetDomainProjectMapAssessees
    @ProjectId VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        a.PROJECT_ID AS ProjectId,
        a.EMP_ID     AS EmpId
    FROM dbo.ITOPS_PROJECT_ASSESSEE a
    WHERE a.ISACTIVE = 1
      AND (@ProjectId IS NULL OR a.PROJECT_ID = @ProjectId)
    ORDER BY a.PROJECT_ID, a.EMP_ID;
END
GO

IF OBJECT_ID('dbo.usp_ITOpsGetCategoriesForDomain', 'P') IS NOT NULL
    DROP PROCEDURE dbo.usp_ITOpsGetCategoriesForDomain;
GO

-- Two modes, matching the two callers that used to duplicate this logic:
--   @DomainId set, @CategoryId NULL  -> every category currently scoped to
--       that domain (GetITOpsCategoriesForDomain), filtered by IsCurrent
--       unless @IncludeExpired = 1.
--   @CategoryId set                  -> that category's full version
--       lineage (same DOMAIN_ID + same NAME, case-insensitive), always
--       every row regardless of @IncludeExpired (GetITOpsCategoryVersions).
-- ParameterCount/VersionCount are computed set-based instead of the
-- per-row dictionary lookups BuildITOpsCategoryRows built in C#.
CREATE PROCEDURE dbo.usp_ITOpsGetCategoriesForDomain
    @DomainId INT = NULL,
    @CategoryId INT = NULL,
    @IncludeExpired BIT = 0
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Today DATE = CAST(GETDATE() AS DATE);
    DECLARE @LineageDomainId INT;
    DECLARE @LineageName VARCHAR(150);

    IF @CategoryId IS NOT NULL
    BEGIN
        SELECT @LineageDomainId = DOMAIN_ID, @LineageName = LTRIM(RTRIM(NAME))
        FROM dbo.ITOPS_CATEGORY
        WHERE ID = @CategoryId;
    END

    ;WITH Scoped AS (
        SELECT c.*
        FROM dbo.ITOPS_CATEGORY c
        WHERE
            (
                @CategoryId IS NOT NULL
                AND c.DOMAIN_ID = @LineageDomainId
                AND LTRIM(RTRIM(c.NAME)) = @LineageName
            )
            OR
            (
                @CategoryId IS NULL
                AND c.DOMAIN_ID = @DomainId
                AND (@IncludeExpired = 1 OR (c.ISACTIVE = 1 AND (c.END_DATE IS NULL OR c.END_DATE > @Today)))
            )
    )
    SELECT
        s.ID                                                            AS CategoryId,
        s.DOMAIN_ID                                                     AS DomainId,
        s.NAME                                                          AS Name,
        s.DISPLAY_ORDER                                                 AS DisplayOrder,
        s.START_DATE                                                    AS StartDate,
        s.END_DATE                                                      AS EndDate,
        CAST(CASE WHEN s.ISACTIVE = 1 AND (s.END_DATE IS NULL OR s.END_DATE > @Today) THEN 1 ELSE 0 END AS BIT) AS IsCurrent,
        (
            SELECT COUNT(*) FROM dbo.ITOPS_PARAMETER p
            WHERE p.CATEGORY_ID = s.ID
              AND p.ISACTIVE = 1
              AND (p.END_DATE IS NULL OR p.END_DATE > @Today)
        )                                                                AS ParameterCount,
        (
            SELECT COUNT(*) FROM dbo.ITOPS_CATEGORY lin
            WHERE lin.DOMAIN_ID = s.DOMAIN_ID
              AND LTRIM(RTRIM(lin.NAME)) = LTRIM(RTRIM(s.NAME))
        )                                                                AS VersionCount
    FROM Scoped s
    ORDER BY s.DISPLAY_ORDER, s.NAME, s.START_DATE;
END
GO

-- ============================================================
-- STEP 8: Report stored procedures + registration (base version - overwritten by step 9)
-- ============================================================
----------------------------------------------------IT Operations Maturity - Reports page (real backend data)----------------------------------------------
-- Registers reports the same way every other CSM report is registered - a stored
-- procedure executed via AppRepository.GetTable() (see
-- ITOperationMaturityController.GetITOpsReportData, which mirrors
-- AllSysController.GetSpData) - registered into the SHARED REPORTS_SP_DETAILS/
-- REPORTS_PARAMS tables (the module's own ITOPS_REPORT_SP_DETAILS/ITOPS_REPORT_PARAMS
-- copy was never actually created in the database, so GetITOpsReportSps/Params/Data
-- now read the shared tables directly - "isolation" is a SP_NAME naming convention
-- (must contain "ITOps", case-insensitive) rather than a separate table).
-- GetTable() always runs against the CloudDbContext connection, so this only works
-- where CSP/BAS tables share one physical database (true in this environment).
--
-- V2 SCHEMA REWRITE: the previous version of report_getITOpsMaturityReport referenced
-- columns that no longer exist (ITOPS_ASSESSMENT.CUST_ID/COE_SPOC_EMP_ID/REVIEWER_EMP_ID,
-- ITOPS_FINDING.ASSESSMENT_ID) - it was never actually runnable against the current
-- schema. Account is now resolved via PROJECT.CUST_ID (ITOPS_ASSESSMENT.PROJECT_ID ->
-- PROJECT -> CUSTOMER); COE SPOC/Reviewer come from ITOPS_ASSESSMENT_ASSESSOR/
-- ITOPS_ASSESSMENT_REVIEWER (first-added active row, matching
-- GetITOpsAssessorIds/GetITOpsReviewerIds's own convention); findings resolve through
-- ITOPS_SCORE (ITOPS_FINDING.SCORE_ID -> ITOPS_SCORE.ASSESSMENT_ID).
--
-- Both reports now also take @ProjectId/@DomainId/@AssessmentMasterId (cycle) filters,
-- not just @CustomerId - '-1' (or NULL) means "don't filter on this".

CREATE OR ALTER PROCEDURE [dbo].[report_getITOpsMaturityReport]
    @CustomerId varchar(20) = '-1',
    @ProjectId varchar(20) = '-1',
    @DomainId int = -1,
    @AssessmentMasterId int = -1,
    @BusinessUnit varchar(150) = '-1'
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        c.CUST_NM AS Account,
        p.PROJ_NM AS Project,
        ISNULL(a.BUSINESS_UNIT, 'Unknown') AS BusinessUnit,
        -- "All cycles" is a valid filter selection here (unlike the Dashboard, which
        -- dropped it after the cross-cycle merge bug) - Period lets rows from different
        -- cycles be told apart instead of blending together in one flat list.
        am.CYCLE_LABEL AS Period,
        d.NAME AS DomainName,
        d.CODE AS DomainCode,
        ISNULL(coe.FRST_NM, asr.ASSESSOR_EMP_ID) AS CoeSpoc,
        ISNULL(rev.FRST_NM, rvr.REVIEWER_EMP_ID) AS Reviewer,
        coe.EMAIL_ID AS CoeSpocEmail,
        rev.EMAIL_ID AS ReviewerEmail,
        CASE
            WHEN a.STATUS = 'Suspended' THEN 'Suspended'
            WHEN a.STATUS IN ('Approved', 'Closed') THEN 'Closed'
            ELSE 'Open'
        END AS AssessmentStatus,
        CASE
            WHEN a.STATUS IN ('Suspended', 'Approved', 'Closed') THEN NULL
            WHEN td.MinTargetDate IS NULL THEN NULL
            WHEN td.MinTargetDate < CAST(GETDATE() AS DATE) THEN 'Past Due'
            ELSE 'On Target'
        END AS DueStatus,
        td.MinTargetDate AS TargetDate,
        ISNULL(a.UPDATED_DATE, a.CREATED_DATE) AS LastUpdated,
        DATEDIFF(day, ISNULL(a.UPDATED_DATE, a.CREATED_DATE), GETDATE()) AS DaysSinceUpdate,
        CASE WHEN a.STATUS IN ('Draft', 'ReturnedForRevision')
             AND DATEDIFF(day, ISNULL(a.UPDATED_DATE, a.CREATED_DATE), GETDATE()) > 15
             THEN 1 ELSE 0 END AS DraftOver15Days,
        CASE WHEN a.STATUS IN ('Draft', 'ReturnedForRevision')
             AND DATEDIFF(day, ISNULL(a.UPDATED_DATE, a.CREATED_DATE), GETDATE()) > 30
             THEN 1 ELSE 0 END AS DraftOver30Days,
        CASE WHEN DATEDIFF(day, ISNULL(a.UPDATED_DATE, a.CREATED_DATE), GETDATE()) > 30
             THEN 1 ELSE 0 END AS NoManagementUpdate,
        CASE WHEN DATEDIFF(day, ISNULL(a.UPDATED_DATE, a.CREATED_DATE), GETDATE()) > 60
             THEN 1 ELSE 0 END AS LongDated,
        ISNULL(f.FindingsAccepted, 0) AS FindingsAccepted,
        ISNULL(f.FindingsRejected, 0) AS FindingsRejected,
        ISNULL(f.FindingsPending, 0) AS FindingsPending,
        sc.AverageScore AS AverageScore,
        sc.MaturityPercent AS MaturityPercent,
        a.ID AS AssessmentId,
        d.ID AS DomainId,
        p.CUST_ID AS CustomerId
    FROM ITOPS_ASSESSMENT a
    JOIN ITOPS_DOMAIN d ON d.ID = a.DOMAIN_ID AND d.ISACTIVE = 1
    JOIN PROJECT p ON p.PROJ_ID = a.PROJECT_ID
    JOIN CUSTOMER c ON c.CUST_ID = p.CUST_ID
    LEFT JOIN ITOPS_ASSESSMENT_MASTER am ON am.ID = a.ASSESSMENT_MASTER_ID
    OUTER APPLY (
        SELECT TOP 1 ASSESSOR_EMP_ID
        FROM ITOPS_ASSESSMENT_ASSESSOR
        WHERE ASSESSMENT_ID = a.ID AND ISACTIVE = 1
        ORDER BY ID
    ) asr
    OUTER APPLY (
        SELECT TOP 1 REVIEWER_EMP_ID
        FROM ITOPS_ASSESSMENT_REVIEWER
        WHERE ASSESSMENT_ID = a.ID AND ISACTIVE = 1
        ORDER BY ID
    ) rvr
    LEFT JOIN EMP_INFO coe ON coe.EMP_ID = asr.ASSESSOR_EMP_ID AND coe.DOR IS NULL
    LEFT JOIN EMP_INFO rev ON rev.EMP_ID = rvr.REVIEWER_EMP_ID AND rev.DOR IS NULL
    LEFT JOIN (
        SELECT s.ASSESSMENT_ID, MIN(fnd.TARGET_DATE) AS MinTargetDate
        FROM ITOPS_SCORE s
        JOIN ITOPS_FINDING fnd ON fnd.SCORE_ID = s.ID
        WHERE fnd.ISACTIVE = 1 AND fnd.STATUS = 'Open' AND fnd.TARGET_DATE IS NOT NULL
        GROUP BY s.ASSESSMENT_ID
    ) td ON td.ASSESSMENT_ID = a.ID
    LEFT JOIN (
        SELECT s.ASSESSMENT_ID,
            SUM(CASE WHEN fnd.STATUS = 'Accepted' THEN 1 ELSE 0 END) AS FindingsAccepted,
            SUM(CASE WHEN fnd.STATUS = 'Rejected' THEN 1 ELSE 0 END) AS FindingsRejected,
            SUM(CASE WHEN fnd.STATUS = 'Open' THEN 1 ELSE 0 END) AS FindingsPending
        FROM ITOPS_SCORE s
        JOIN ITOPS_FINDING fnd ON fnd.SCORE_ID = s.ID
        WHERE fnd.ISACTIVE = 1
        GROUP BY s.ASSESSMENT_ID
    ) f ON f.ASSESSMENT_ID = a.ID
    LEFT JOIN (
        SELECT ASSESSMENT_ID,
            CAST(AVG(CAST(SCORE_VALUE AS DECIMAL(10, 2))) AS DECIMAL(10, 2)) AS AverageScore,
            CAST(AVG(CAST(SCORE_VALUE AS DECIMAL(10, 2))) / 5.0 * 100 AS DECIMAL(10, 2)) AS MaturityPercent
        FROM ITOPS_SCORE
        WHERE ISACTIVE = 1 AND SCORE_VALUE IS NOT NULL
        GROUP BY ASSESSMENT_ID
    ) sc ON sc.ASSESSMENT_ID = a.ID
    WHERE a.ISACTIVE = 1
      AND (@CustomerId = '-1' OR p.CUST_ID = @CustomerId)
      AND (@ProjectId = '-1' OR a.PROJECT_ID = @ProjectId)
      AND (@DomainId = -1 OR d.ID = @DomainId)
      AND (@AssessmentMasterId = -1 OR a.ASSESSMENT_MASTER_ID = @AssessmentMasterId)
      AND (@BusinessUnit = '-1' OR a.BUSINESS_UNIT = @BusinessUnit)
    ORDER BY c.CUST_NM, am.CYCLE_LABEL, d.DISPLAY_ORDER;
END
GO

-- New: parameter-level detail report - one row per (assessment, parameter), with the
-- category/question/score/assessor/reviewer/assessee/finding-status columns requested
-- for the Reports page's second report.
CREATE OR ALTER PROCEDURE [dbo].[report_getITOpsParameterDetailReport]
    @CustomerId varchar(20) = '-1',
    @ProjectId varchar(20) = '-1',
    @DomainId int = -1,
    @AssessmentMasterId int = -1,
    @BusinessUnit varchar(150) = '-1'
AS
BEGIN
    SET NOCOUNT ON;

    -- Driven from ITOPS_ASSESSMENT x ITOPS_PARAMETER (every currently-effective parameter
    -- for the assessment's domain), NOT from ITOPS_SCORE - the earlier version started
    -- from ITOPS_SCORE, so a parameter with no score/finding yet simply never appeared
    -- (silently dropped) instead of showing up with "N/A". Score/finding are LEFT JOINed
    -- on, so every question in the domain always has a row.
    SELECT
        c.CUST_NM AS Account,
        p.PROJ_NM AS Project,
        ISNULL(a.BUSINESS_UNIT, 'Unknown') AS BusinessUnit,
        am.CYCLE_LABEL AS Period,
        d.NAME AS DomainName,
        cat.NAME AS Category,
        par.NAME AS Parameter,
        par.DEFINITION AS Question,
        s.SCORE_VALUE AS Score,
        asr.AssessorNames AS Assessor,
        rvr.ReviewerNames AS Reviewer,
        -- Assessee is who's ASSIGNED to the assessment (ITOPS_ASSESSMENT_ASSESSEE, multi-
        -- select, same as assessor/reviewer) - not ITOPS_FINDING.ASSESSEE_EMP_ID, which the
        -- app never actually populates (no code path writes it), so it always reads empty.
        asse.AssesseeNames AS Assessee,
        ISNULL(f.STATUS, 'N/A') AS FindingStatus,
        a.ID AS AssessmentId,
        d.ID AS DomainId
    FROM ITOPS_ASSESSMENT a
    JOIN ITOPS_DOMAIN d ON d.ID = a.DOMAIN_ID AND d.ISACTIVE = 1
    JOIN ITOPS_CATEGORY cat ON cat.DOMAIN_ID = d.ID AND cat.ISACTIVE = 1
        AND (cat.END_DATE IS NULL OR cat.END_DATE > CAST(GETDATE() AS DATE))
    JOIN ITOPS_PARAMETER par ON par.CATEGORY_ID = cat.ID AND par.ISACTIVE = 1
        AND (par.END_DATE IS NULL OR par.END_DATE > CAST(GETDATE() AS DATE))
    JOIN PROJECT p ON p.PROJ_ID = a.PROJECT_ID
    JOIN CUSTOMER c ON c.CUST_ID = p.CUST_ID
    LEFT JOIN ITOPS_ASSESSMENT_MASTER am ON am.ID = a.ASSESSMENT_MASTER_ID
    LEFT JOIN ITOPS_SCORE s ON s.ASSESSMENT_ID = a.ID AND s.PARAMETER_ID = par.ID AND s.ISACTIVE = 1
    LEFT JOIN ITOPS_FINDING f ON f.SCORE_ID = s.ID AND f.ISACTIVE = 1
    OUTER APPLY (
        SELECT STRING_AGG(ISNULL(e.FRST_NM, aa.ASSESSOR_EMP_ID), ', ') AS AssessorNames
        FROM ITOPS_ASSESSMENT_ASSESSOR aa
        LEFT JOIN EMP_INFO e ON e.EMP_ID = aa.ASSESSOR_EMP_ID AND e.DOR IS NULL
        WHERE aa.ASSESSMENT_ID = a.ID AND aa.ISACTIVE = 1
    ) asr
    OUTER APPLY (
        SELECT STRING_AGG(ISNULL(e.FRST_NM, ar.REVIEWER_EMP_ID), ', ') AS ReviewerNames
        FROM ITOPS_ASSESSMENT_REVIEWER ar
        LEFT JOIN EMP_INFO e ON e.EMP_ID = ar.REVIEWER_EMP_ID AND e.DOR IS NULL
        WHERE ar.ASSESSMENT_ID = a.ID AND ar.ISACTIVE = 1
    ) rvr
    OUTER APPLY (
        SELECT STRING_AGG(ISNULL(e.FRST_NM, ae.ASSESSEE_EMP_ID), ', ') AS AssesseeNames
        FROM ITOPS_ASSESSMENT_ASSESSEE ae
        LEFT JOIN EMP_INFO e ON e.EMP_ID = ae.ASSESSEE_EMP_ID AND e.DOR IS NULL
        WHERE ae.ASSESSMENT_ID = a.ID AND ae.ISACTIVE = 1
    ) asse
    WHERE a.ISACTIVE = 1
      AND (@CustomerId = '-1' OR p.CUST_ID = @CustomerId)
      AND (@ProjectId = '-1' OR a.PROJECT_ID = @ProjectId)
      AND (@DomainId = -1 OR d.ID = @DomainId)
      AND (@AssessmentMasterId = -1 OR a.ASSESSMENT_MASTER_ID = @AssessmentMasterId)
      AND (@BusinessUnit = '-1' OR a.BUSINESS_UNIT = @BusinessUnit)
    ORDER BY c.CUST_NM, p.PROJ_NM, d.DISPLAY_ORDER, cat.DISPLAY_ORDER, par.DISPLAY_ORDER;
END
GO

