SELECT dm.NAME AS DomainName, c.NAME AS CategoryName, pm.NAME AS ParameterName, pm.DISPLAY_ORDER,
       (SELECT COUNT(*) FROM ITOPS_PARAMETER_LEVEL pl WHERE pl.PARAMETER_ID = pm.ID) AS LevelCount
FROM ITOPS_PARAMETER pm
JOIN ITOPS_CATEGORY c ON c.ID = pm.CATEGORY_ID
JOIN ITOPS_DOMAIN dm ON dm.ID = c.DOMAIN_ID
WHERE dm.CODE = 'soc'
ORDER BY c.DISPLAY_ORDER, pm.DISPLAY_ORDER;
GO

